const s = $input.first().json.sheets[0];
const hex = (c) => { if (!c) return '-'; const f = (v) => Math.round((v ?? 0) * 255).toString(16).padStart(2, '0'); return f(c.red) + f(c.green) + f(c.blue); };
const rows = s.data[0].rowData || [];
const colores = {};
const filas = rows.map((r, i) => {
  const v = (r.values || []);
  const bg = v.slice(0, 11).map((c) => hex(c.effectiveFormat && c.effectiveFormat.backgroundColor));
  bg.forEach((h) => { colores[h] = (colores[h] || 0) + 1; });
  const txt = v.slice(0, 5).map((c) => String(c.formattedValue ?? '').replace(/\s+/g, ' ').slice(0, 26));
  return (i + 1) + '|' + bg.join(',') + '|' + txt.join(' ¦ ');
});
return [{ json: {
  propiedades: s.properties,
  merges: (s.merges || []).length,
  merges_ejemplo: (s.merges || []).slice(0, 14),
  protegidos: (s.protectedRanges || []).length,
  anchos: (s.data[0].columnMetadata || []).map((c) => c.pixelSize).join(','),
  colores,
  filas
} }];
